    function requestTab(targetid, tabtype, ajaxurl, that) {
        dom_loaded(ajaxurl)
        var tab_id = "#infoLayer_" + tabtype + "_" + targetid;

        $(".detailsContainer>div").css("display", "none");

        if (tab_id == last_tab_id)      // if last id opened was this one, just return after close
        {
            last_tab_id = "";
            return;
        }

        ajaxPost(ajaxurl, null, function done(data) {
            $(tab_id).empty().html(data);
            $(tab_id).executeReady();
            $(".detailsContainer>div").css("display", "none");
            $(tab_id).animate({ height: 'toggle', opacity: '1' });
            last_tab_id = tab_id;
            $(".dropbutton").removeClass("ui-focus")
            $(that).addClass("ui-focus")
        });
    }


